files=['IMPLEMENTADOR.md','README.md','docs/PLANO-DE-IMPLEMENTACAO.md','docs/PLANO-DE-VALIDACAO.md','docs/RFC-0001-ARQUITETURA.md','docs/STATUS-IMPLEMENTACAO.md','docs/contracts/m1.md','docs/decisoes/CONTEXTO-P3.md','docs/relatorios/REVISAO-L5.md']
def git(*args):return subprocess.check_output(['git',*args],cwd=root,text=True).strip()
def sha(p):return hashlib.sha256((root/p).read_bytes()).hexdigest()
errors=[];links=0
for name in files:
 p=root/name
 for target in re.findall(r'\]\(([^)]+)\)',p.read_text()):
  if '://' in target or target.startswith('#'):continue
  target=target.split('#')[0]
  if target:
   links+=1
   if not (p.parent/target).exists():errors.append(f'broken link: {name} {target}')
def cards(text):
 parts=re.split(r'^### (M[01]-\d+(?:\.R\d+)?) — ',text,flags=re.M);result={}
 for i in range(1,len(parts),2):
  d=re.search(r'\*\*Depende de:\*\*(.*?)(?=\*\*|\n)',parts[i+1]);assert d
  result[parts[i]]=re.findall(r'M[01]-\d+(?:\.R\d+)?',d.group(1))
 return result
plan=cards((root/'docs/PLANO-DE-IMPLEMENTACAO.md').read_text());old=cards(git('show','HEAD:docs/PLANO-DE-IMPLEMENTACAO.md'))
assert len(plan)==41 and plan==old
seen=set();active=set()
def visit(c):
 assert c not in active,'dependency cycle';
 if c in seen:return
 active.add(c)
 for d in plan[c]:assert d in plan;visit(d)
 active.remove(c);seen.add(c)
for c in plan:visit(c)
def states(text):return dict(re.findall(r'^\| (M[01]-\d+(?:\.R\d+)?) \|[^\n]*?\| ([^|]+?) \|',text,re.M))
state=(root/'docs/STATUS-IMPLEMENTACAO.md').read_text();oldstate=git('show','HEAD:docs/STATUS-IMPLEMENTACAO.md')
assert states(state)==states(oldstate) and set(plan)==set(states(state))
assert all(f'| {g} | não avaliado |' in state for g in ['G0','G1','G2'])
review=(root/'docs/relatorios/REVISAO-L5.md').read_text()
assert all(x in review for x in ['L5-01','L5-02','L5-03','L5-04','L5-05/06'])
for code in ['L5-C01','L5-P01','L5-P02','L5-R01','L5-E01']:assert f'| {code} |' in review
rec=json.loads((log/'evidencias.json').read_text());assert rec['result']=='passed' and len(rec['records'])==7 and all(r['exit_code']==0 for r in rec['records'])
assert rec['source_hashes_verified']==59 and rec['native_artifact_hashes_verified']==199
assert rec['base_commit']==git('rev-parse','HEAD')
changed=git('diff','--name-only').splitlines()+git('ls-files','--others','--exclude-standard').splitlines()
allowed=set(files+['docs/relatorios/logs/revisao-L5/documentacao.json','docs/relatorios/logs/revisao-L5/evidencias.json'])
if set(changed)!=allowed:errors.append('unexpected/missing changes '+str(set(changed)^allowed))
check=subprocess.run(['git','diff','--check'],cwd=root,capture_output=True,text=True)
if check.returncode:errors.append(check.stdout+check.stderr)
inputs=['docs/relatorios/L5.md','docs/relatorios/logs/L5/ci-native/native-receipt.json','docs/relatorios/logs/L5/ci-native/run-completed.json','docs/relatorios/logs/L5/integration/source-manifest-final.json','eval/context/README.md','eval/qualification/l5-slot-plan.json','eval/reports/m0-workers-persistent.md','eval/workers/matrix-design.json','crates/xrai-eval/src/context_spike.rs','eval/scripts/verify_context.py','eval/scripts/verify_worker_measurement.py','eval/scripts/verify_slot_plan.py','docs/contracts/experimental-p3/verify.py','docs/contracts/experimental-p3/schema.json','docs/contracts/experimental-p3/README.md']
